DO $$
DECLARE
    target_release CONSTANT TEXT := 'evil-hunter-1.411.buildings-v1';
BEGIN
    IF (SELECT count(*) FROM building_capability_definition WHERE release_id = target_release) <> 10
       OR (SELECT count(*) FROM economy_resource_definition WHERE release_id = target_release) <> 1109
       OR (SELECT count(*) FROM economy_item_definition WHERE release_id = target_release) <> 1107
       OR (SELECT count(*) FROM economy_item_localization WHERE release_id = target_release) <> 15484
       OR (SELECT count(*) FROM economy_item_price_component WHERE release_id = target_release) <> 0
       OR (SELECT count(*) FROM economy_item_hunter_tier_price WHERE release_id = target_release) <> 3395
       OR (SELECT count(*) FROM economy_product_definition WHERE release_id = target_release) <> 3457
       OR (SELECT count(*) FROM economy_product_amount WHERE release_id = target_release) <> 13192
       OR (SELECT count(*) FROM economy_product_service WHERE release_id = target_release) <> 52
       OR (SELECT count(*) FROM economy_product_service_completion WHERE release_id = target_release) <> 131
       OR (SELECT count(*) FROM economy_product_conversion_option WHERE release_id = target_release) <> 214
       OR (SELECT count(*) FROM economy_product_random_output WHERE release_id = target_release) <> 10
       OR EXISTS (
           SELECT 1 FROM economy_item_hunter_tier_price
           WHERE release_id = target_release
           GROUP BY item_id
           HAVING min(tier) <> 1 OR max(tier) <> count(*)
       )
       OR EXISTS (
           SELECT 1 FROM economy_product_amount
           WHERE release_id = target_release
           GROUP BY product_id, amount_kind
           HAVING min(ordinal) <> 0 OR max(ordinal) <> count(*) - 1
       )
       OR EXISTS (
           SELECT 1 FROM economy_product_service_completion
           WHERE release_id = target_release
           GROUP BY product_id
           HAVING min(ordinal) <> 0 OR max(ordinal) <> count(*) - 1
       )
       OR EXISTS (
           SELECT 1 FROM economy_product_conversion_option
           WHERE release_id = target_release
           GROUP BY product_id
           HAVING min(ordinal) <> 0 OR max(ordinal) <> count(*) - 1
       )
    THEN
        RAISE EXCEPTION 'normalized building gameplay content count mismatch';
    END IF;
END $$;
